import {createClient} from '@supabase/supabase-js';
import {canAttend,escapeHTML as e,date} from './domain.js';
import './style.css';
import {validateRegistration} from './registration.js';
const root=document.querySelector('#app');
const url=import.meta.env.VITE_SUPABASE_URL,key=import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;
const db=url&&key?createClient(url,key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}}):null;
let user=null,profile=null,role={role:'driver',verified:false},settings={},championships=[],races=[],attendance=[],notes=[],penalties=[],reports=[],drivers=[],checkins=[],standings=[],entries=[],selectedRace='',amendSection='settings',showPast=false,modalState=null,champ='',factor=null,qr='',setupKey='',slide=0,loading=false;
const query=async q=>{const {data,error}=await q;if(error)throw error;return data};
const action=(action,payload={})=>query(db.rpc('league_action',{action,payload}));
let refreshPromise=null,revealObserver=null,slideshowPaused=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const edgeKey=import.meta.env.VITE_SUPABASE_EDGE_ANON_KEY;
const route=()=>location.hash.slice(1).split('?')[0]||'home';
const go=path=>{location.hash=path};
const toast=message=>{document.querySelector('#toast').textContent=message;clearTimeout(toast.timer);toast.timer=setTimeout(()=>document.querySelector('#toast').textContent='',6500)};
const input=(name,label,type='text',value='',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${e(value)}" ${extra}></label>`;
const select=(name,label,options,value='')=>`<label>${label}<select name="${name}">${options.map(([v,t])=>`<option value="${e(v)}" ${v===value?'selected':''}>${e(t)}</option>`).join('')}</select></label>`;
const brandName='Sector Vale Racing';
const categories=[['GT3','GT3'],['GT4','GT4'],['Both','GT3 & GT4']];
const levels=[['Beginner','Beginner — < 1,500 iRating'],['Intermediate','Intermediate — 1,500–2,500 iRating'],['Experienced','Expert — > 2,500 iRating']];
const textarea=(name,label,value='',extra='')=>`<label>${label}<textarea name="${name}" ${extra}>${e(value)}</textarea></label>`;
const form=(name,body,label='Save')=>`<form data-form="${name}">${body}<button class="primary" type="submit">${label}</button></form>`;
const badge=value=>`<span class="badge ${e(value)}">${e(value)}</span>`;
const empty=text=>`<p class="empty">${e(text)}</p>`;
const sessionSelect=()=>select('session_id','Race session',races.map(r=>[r.id,`${r.title} · ${date(r.starts_at)}`]));
const driverSelect=()=>select('driver_id','Driver',drivers.filter(p=>p.status==='approved').map(p=>[p.id,`${p.forename} ${p.surname}`]));
const table=(head,rows)=>`<div class="tablewrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
function shell(body){
 const unread=notes.filter(n=>!n.read_at).length;
 root.innerHTML=`<header><a class="brand" href="#home"><img class="brand-logo" src="/branding/SVR-primary.png" alt="Sector Vale Racing — home" width="220" height="89"></a><nav aria-label="Main navigation"><a href="#series">GT3 & GT4</a><a href="#championships">Championships</a><a href="#calendar">Calendar</a>${user?`<a href="#dashboard">Dashboard</a><a class="icon" href="#notifications" aria-label="Notifications, ${unread} unread"><svg width="22" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>${unread?`<b>${unread}</b>`:''}</a><a class="icon" href="#profile" aria-label="Your profile">◉</a>${role.role!=='driver'?'<a href="#admin">Race control</a>':''}<button data-click="logout" class="quiet">Sign out</button>`:`<a href="#login">Sign in</a><a class="button ${settings.registration_open?'primary':''}" href="#register">${settings.registration_open?'Pre-register ↗':'Pre-registration closed'}</a>`}</nav></header><main>${body}</main><footer><span>${e(brandName)} · Race with respect.</span><div><a href="#privacy">Privacy</a><a href="#regulations">Racing regulations</a><a href="#credits">Image credits</a><span>All times: UK</span></div></footer>${modalHTML()}`;
 if(modalState)document.querySelector("#league-modal").showModal();
 revealObserver?.disconnect();
 if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver' in window){revealObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target)}},{threshold:0.06});root.querySelectorAll('.racecard,.featuregrid article,.panel,.notification').forEach(el=>{el.classList.add('reveal-ready');revealObserver.observe(el)})}
}
function refresh(){if(refreshPromise)return refreshPromise;refreshPromise=loadLeague().finally(()=>refreshPromise=null);return refreshPromise}
async function loadLeague(){
 if(!db){shell(`<section class="page narrow"><p class="eyebrow">CONFIGURATION REQUIRED</p><h1>League connection pending</h1><p>This application needs its dedicated Supabase project before registration and racing features can run.</p></section>`);return}

 try{
 user=(await db.auth.getUser()).data.user;
 [settings,championships,races]=await Promise.all([
 query(db.from('league_settings').select('*').single()),query(db.from('championships').select('*').order('season',{ascending:false})),query(db.from('race_sessions').select('*').order('starts_at'))
 ]);
 if(!champ||!championships.some(c=>c.id===champ))champ=championships[0]?.id||'';
 profile=null;role={role:'driver',verified:false};attendance=[];notes=[];penalties=[];reports=[];drivers=[];checkins=[];entries=[];
 if(user){
 [profile,role,attendance,notes,penalties,reports]=await Promise.all([
 query(db.from('profiles').select('*').eq('id',user.id).single()),action('role'),query(db.from('attendance').select('*')),query(db.from('notifications').select('*').order('created_at',{ascending:false}).limit(100)),query(db.from('penalties').select('*').order('created_at',{ascending:false})),query(db.from('incidents').select('*').order('created_at',{ascending:false}))
 ]);
 entries=await query(db.from('championship_entries').select('*'));
 if(role.verified)[drivers,checkins]=await Promise.all([query(db.from('profiles').select('*').order('surname')),query(db.from('checkins').select('*'))]);
 }
 standings=champ?await query(db.rpc('championship_standings',{championship:champ})):[];
 render();return true;
 }catch(err){shell(`<section class="page narrow"><h1>We couldn’t load the league</h1><p>${e(err.message)}</p><button data-click="retry">Try again</button></section>`);return false}
}
function raceCards(list,withAttendance=false){return list.length?list.map(r=>{
 const attending=attendance.find(a=>a.session_id===r.id&&a.driver_id===user?.id)?.attending||false;
 const deadline=new Date(new Date(r.starts_at).getTime()-1800000);
 const member=entries.some(x=>x.championship_id===r.championship_id&&x.driver_id===user?.id);
 const open=canAttend(r.starts_at,Date.now(),r.status)&&r.status==='scheduled'&&profile?.status==='approved'&&member;
 return `<article class="racecard"><div class="race-date">${new Date(r.starts_at).toLocaleDateString('en-GB',{day:'2-digit',month:'short',timeZone:'Europe/London'})}</div><div class="race-detail"><small>${e(championships.find(c=>c.id===r.championship_id)?.name||'Championship')}</small><h3>${e(r.title)}</h3><p>${e(r.track)} · ${date(r.starts_at)}</p>${withAttendance?`<small>Attendance closes ${date(deadline)}</small>`:''}</div><div>${badge(r.status)}${withAttendance?`<label class="toggle"><input type="checkbox" data-attend="${r.id}" ${attending?'checked':''} ${open?'':'disabled'}><span>${attending?'Attending':!member?'Join championship':open?'Attend':'Closed'}</span></label>`:''}</div></article>`
 }).join(''):empty('No races have been published yet.');}
function championshipPicker(){return select('championship','Championship',championships.map(c=>[c.id,`${c.name} · ${c.season}`]),champ)}
function standingsTable(){return standings.length?table(['Pos','Driver','Wins','Points'],standings.map(s=>[`${s.position}`,e(s.display_name),s.wins,`<strong>${s.points}</strong>`])):empty('Standings will appear when the first results are published.');}
function render(){
 const page=route();
 if(['dashboard','profile','notifications','incident','admin','steward','amend','verify','password'].includes(page)&&!user){go('login');return}
 let body='';
 if(page==='home'||page==='series')body=`<section class="hero svr-hero"><div class="slides" aria-label="Racing action slideshow">${['/images/gt3-0.jpg','/images/gt3-1.jpg','/images/gt3-2.jpg'].map((p,i)=>`<div class="slide ${i===slide?'active':''}" style="background-image:url('${p}')"></div>`).join('')}</div><div class="herocopy"><p class="eyebrow">SECTOR VALE RACING / iRACING LEAGUE</p><h1>Find your<br>next <em>limit.</em></h1><p>Close racing. Shared ambition. A community built around respect. Take the first step towards your next season with Sector Vale Racing.</p><div class="hero-actions"><a class="button primary large" href="${user?'#dashboard':'#register'}">${user?'Driver dashboard':settings.registration_open?'Pre-register your interest':'Pre-registration closed'} ↗</a><a class="button glass large" href="#series">Explore GT3 & GT4 ↓</a></div><p class="entry-note">Register your interest. Race entry is confirmed separately.</p></div><div class="slidecontrols"><span>GT3 + GT4 <b>/</b> BUILT FOR THE RACER</span><button data-click="prevslide" aria-label="Previous racing image">←</button><button data-click="nextslide" aria-label="Next racing image">→</button></div><span class="hero-side" aria-hidden="true">SVR / THE NEXT CHAPTER</span></section><div class="brand-strip"><span>PRECISION.</span><span>RESPECT.</span><span>COMPETITION.</span><span class="strip-end">SECTOR VALE RACING</span></div><section class="page svr-home"><div class="sectionhead"><div><p class="eyebrow">TWO CLASSES. ONE COMMUNITY.</p><h2>Choose your next challenge.</h2></div><span class="section-tag">GT3 / GT4</span></div><p class="section-intro">Tell us where you want to race. Choose GT3, GT4 or both when you pre-register — your preference helps shape the league.</p><div class="series-grid" id="series-list"><article class="series-card"><div class="series-number" aria-hidden="true">03</div><p class="eyebrow">THE GT3 EXPERIENCE</p><h3>Push the pace.</h3><p>For drivers drawn to GT3 machinery and close competition. Bring your focus, find your rhythm and make every lap count.</p><a href="#register?category=GT3">${settings.registration_open?'Pre-register for GT3':'View pre-registration'} <span>↗</span></a></article><article class="series-card gt4"><div class="series-number" aria-hidden="true">04</div><p class="eyebrow">THE GT4 EXPERIENCE</p><h3>Master the race.</h3><p>For drivers who enjoy GT4 racing and building consistency. Develop your racecraft and share the track with a respectful community.</p><a href="#register?category=GT4">${settings.registration_open?'Pre-register for GT4':'View pre-registration'} <span>↗</span></a></article></div><section class="registration-explainer" aria-labelledby="prereg-title"><div><p class="eyebrow">YOUR FIRST STEP</p><h2 id="prereg-title">Interest today.<br>Racing comes next.</h2></div><div><p>Pre-registration creates your driver profile and records your GT3 / GT4 preference. The league team reviews applications before drivers can attend races.</p><p class="muted">It does not reserve a grid place or confirm race entry. Championship membership and session attendance are handled separately.</p><a class="text-link" href="${user?'#dashboard':'#register'}">${user?'Open your driver dashboard':'Create your driver profile'} ↗</a></div></section><div class="sectionhead"><div><p class="eyebrow">ON THE HORIZON</p><h2>The next lights out.</h2></div><a href="#calendar">Full calendar ↗</a></div>${raceCards(races.filter(r=>new Date(r.starts_at)>new Date()&&r.status!=='cancelled').slice(0,3))}<div class="featuregrid"><article><span>01 / COMPETE</span><h3>Make every lap count.</h3><p>Follow championship standings and see your season take shape.</p></article><article><span>02 / CONNECT</span><h3>Find your people.</h3><p>A shared passion for racing, from the first practice lap to the chequered flag.</p></article><article><span>03 / RESPECT</span><h3>Race the right way.</h3><p>Published regulations, incident reports and steward decisions support fair competition.</p></article></div></section>`;
 else if(page==='register')body=`<section class="page narrow"><p class="eyebrow">YOUR NEXT CHAPTER</p><h1>Your next chapter starts here.</h1><p>Pre-register your interest in GT3, GT4 or both. Create a driver profile for league review.</p><p class="notice">Pre-registration does not reserve a grid place or confirm race entry. Championship membership and session attendance are separate steps.</p>${settings.registration_open?form('register',`<div class="twocol">${input('forename','Forename','text','','required maxlength="80" autocomplete="given-name"')}${input('surname','Surname','text','','required maxlength="80" autocomplete="family-name"')}</div>${input('email','Email','email','','required autocomplete="email"')}${input('password','Password','password','','required minlength="12" autocomplete="new-password"')}${select('category','Racing category preference',categories,['GT3','GT4','Both'].includes(new URLSearchParams(location.hash.split('?')[1]).get('category'))?new URLSearchParams(location.hash.split('?')[1]).get('category'):'GT3')}${select('experience','iRating band',levels)}<label class="check"><input name="privacy_acknowledged" type="checkbox" required><span>I have read the <a href="#privacy" target="_blank" rel="noopener">privacy notice</a> and understand how my information is used to manage the league.</span></label><label class="check"><input name="regulations_accepted" type="checkbox" required><span>I accept the <a href="#regulations" target="_blank" rel="noopener">racing regulations</a>.</span></label><p class="muted">Your public race results use your forename and surname initial. Your email is private. No email-confirmation link is needed; the organiser reviews applications before drivers can attend races.</p>`,'Pre-register →'):empty('Registration is not open yet. Please check back once the league publishes its privacy notice and racing regulations.')}<p>Already registered? <a href="#login">Sign in</a></p></section>`;
 else if(page==='setup')body=`<section class="page narrow"><p class="eyebrow">LEAGUE OWNER</p><h1>Set up your account.</h1><p>This route is reserved for the owner email assigned during deployment. Your email must be verified before any staff role is assigned, and an authenticator code is required to enter race control.</p>${form('owner_setup',input('forename','Forename','text','','required maxlength="80" autocomplete="given-name"')+input('surname','Surname','text','','required maxlength="80" autocomplete="family-name"')+input('email','Owner email','email','','required autocomplete="email"')+input('password','Password','password','','required minlength="12" autocomplete="new-password"')+select('category','Racing category preference',categories,['GT3','GT4','Both'].includes(new URLSearchParams(location.hash.split('?')[1]).get('category'))?new URLSearchParams(location.hash.split('?')[1]).get('category'):'GT3')+select('experience','iRating band',levels),'Create owner account')}<p class="muted">Your account details are used for league administration and processed by Supabase. Public driver registration remains closed until the owner publishes the privacy notice and racing regulations. This setup does not record acceptance of unpublished racing regulations.</p></section>`;
 else if(page==='login')body=`<section class="page narrow"><p class="eyebrow">WELCOME BACK</p><h1>Back on track.</h1>${form('login',input('email','Email','email','','required autocomplete="email"')+input('password','Password','password','','required autocomplete="current-password"'),'Sign in →')}<a href="#reset">Forgot your password?</a></section>`;
 else if(page==='reset')body=`<section class="page narrow"><p class="eyebrow">ACCOUNT SUPPORT</p><h1>Need help signing in?</h1><p>Contact the league organiser for account recovery. Include the email you registered with; do not send your password or authenticator codes.</p><a class="button primary" href="mailto:${e(settings.privacy_email)}?subject=SVR%20account%20help">Contact league support ↗</a><p>Already signed in? You can change your password in your profile.</p><a href="#login">Back to sign in</a></section>`;
 else if(page==='password')body=`<section class="page narrow"><h1>Choose a new password</h1>${form('password',input('password','New password','password','','required minlength="12" autocomplete="new-password"'),'Update password')}</section>`;
 else if(page==='dashboard')body=driverHQ();
 else if(page==='championships')body=championshipsPage();
 else if(page==='calendar')body=`<section class="page"><p class="eyebrow">PLAN YOUR SEASON</p><h1>Race calendar.</h1><p>Attendance closes exactly 30 minutes before each session. All times shown are UK local time.</p>${championshipPicker()}${raceCards(races.filter(r=>r.championship_id===champ),!!user)}</section>`;
 else if(page==='profile')body=`<section class="page narrow"><p class="eyebrow">YOUR DRIVER DETAILS</p><h1>Profile.</h1><p>${e(user.email)} · ${badge(profile.status)}</p>${form('profile',input('forename','Forename','text',profile.forename,'required maxlength="80"')+input('surname','Surname','text',profile.surname,'required maxlength="80"')+select('category','Category preference',categories,profile.category)+select('experience','iRating band',levels,profile.experience)+`<label class="check"><input name="marketing_consent" type="checkbox" ${profile.marketing_consent?'checked':''}><span>Optional marketing emails</span></label>`)}<h2>Account security</h2><a class="button" href="#password">Change password</a> <a class="button" href="#verify">Set up or verify authenticator</a><p>For a copy of your information, correction or account deletion, contact <a href="mailto:${e(settings.privacy_email)}">${e(settings.privacy_email)}</a>.</p></section>`;
 else if(page==='notifications')body=`<section class="page narrow"><p class="eyebrow">FROM RACE CONTROL</p><h1>Notifications.</h1>${notes.length?notes.map(n=>`<article class="notification ${n.read_at?'':'unread'}"><small>${date(n.created_at)}</small><p>${e(n.message)}</p>${!n.read_at?`<button data-read="${n.id}">Mark as read</button>`:''}</article>`).join(''):empty('You’re all caught up. New steward decisions and announcements appear here.')}</section>`;
 else if(page==='incident')body=`<section class="page narrow"><h1>Report an incident.</h1>${form('incident',sessionSelect()+textarea('details','What happened? Include lap, corner and car numbers.','','required minlength="10" maxlength="5000"')+input('evidence_url','Evidence link (optional)','url','','pattern="https://.*"'),'Submit incident')}<h2>Your reports</h2>${reports.filter(r=>r.reporter_id===user.id).map(r=>`<article class="notification">${badge(r.status)}<p>${e(r.details)}</p></article>`).join('')||empty('No incident reports submitted.')}</section>`;
 else if(['admin','steward','amend'].includes(page)){
 if(role.role==='driver')body=`<section class="page narrow"><h1>Access restricted</h1><p>Race control requires an assigned staff role.</p></section>`;
 else if(!role.verified)body=`<section class="page narrow"><h1>Verify your identity.</h1><p>Use your authenticator to unlock race control.</p><a class="button primary" href="#verify">Continue to verification</a></section>`;
 else body=adminPage(page);
 }else if(page==='verify')body=`<section class="page narrow"><h1>Authenticator verification.</h1><p>Staff access requires a six-digit code from your authenticator app.</p><button data-click="setupmfa">Set up / select authenticator</button><div id="mfa-qr">${qr?`<p>Scan this code using your authenticator app.</p><img alt="Authenticator setup QR code" src="${e(qr)}"><h2>Using this phone?</h2><p>Copy the setup key below. In your authenticator app, add an account manually, paste the key and choose <strong>Time based</strong>. Return here and enter its six-digit code.</p><label>Setup key<input id="mfa-setup-key" type="text" readonly autocomplete="off" spellcheck="false" value="${e(setupKey)}"></label><button data-click="copysetupkey" type="button">Copy setup key</button><p class="muted">Keep this key private. It can generate your verification codes.</p>`:''}</div>${factor?form('verify',input('code','Six-digit code','text','','required inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6"'),'Verify'):''}</section>`;
 else if(page==='credits')body=`<section class="page narrow"><h1>Image credits.</h1><p>GT3 racing photography by <a href="https://commons.wikimedia.org/wiki/User:MarcelX42" target="_blank" rel="noopener">MarcelX42</a>, via Wikimedia Commons, licensed under <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a>. Images are resized and cropped by the slideshow; the photography remains available under this license. No endorsement is implied.</p><ul><li><a href="https://commons.wikimedia.org/wiki/File:2024_6_Hours_of_Spa-Francorchamps_Proton_Competition_Ford_Mustang_GT3_No.88_(DSC04264).jpg">Ford Mustang GT3 No.88 at Spa 2024</a></li><li><a href="https://commons.wikimedia.org/wiki/File:2024_6_Hours_of_Spa-Francorchamps_Iron_Dames_Lamborghini_Hurac%C3%A1n_GT3_Evo2_No.85_(DSC02627).jpg">Iron Dames Lamborghini GT3 No.85 at Spa 2024</a></li><li><a href="https://commons.wikimedia.org/wiki/File:2024_6_Hours_of_Spa-Francorchamps_Manthey_PureRxcing_Porsche_911_GT3_R_No.92_(DSC05555).jpg">Porsche 911 GT3 R No.92 at Spa 2024</a></li></ul></section>`;
 else if(page==='privacy'||page==='regulations')body=`<section class="page narrow"><h1>${page==='privacy'?'Privacy notice':'Racing regulations'}</h1><p class="muted">Version ${settings.policy_version}</p><div class="prose">${e(page==='privacy'?settings.privacy_text:settings.regulations)||'The league has not published this document yet.'}</div>${page==='privacy'?`<p>Data controller: ${e(settings.controller_name)}<br>Contact: ${e(settings.privacy_email)}</p>`:''}</section>`;
 else body=`<section class="page narrow"><h1>Page not found</h1><a href="#home">Return home</a></section>`;
 shell(body);
 if(page==='series')document.querySelector('#series-list')?.scrollIntoView();
}
function driverName(id){const d=drivers.find(d=>d.id===id);return d?d.forename+' '+d.surname:'Driver'}
function joinedRaces(){const ids=new Set(entries.filter(x=>x.driver_id===user?.id).map(x=>x.championship_id));return races.filter(r=>ids.has(r.championship_id))}
function futureChampionships(){return championships.filter(c=>{
 const sessions=races.filter(r=>r.championship_id===c.id&&r.status!=='cancelled');
 const times=[c.starts_at,...sessions.map(r=>r.starts_at)].filter(Boolean).map(x=>new Date(x).getTime());
 return c.published&&c.enrollment_open&&times.length&&Math.min(...times)>Date.now()&&!sessions.some(r=>['checkin','live','finished'].includes(r.status))&&!entries.some(x=>x.championship_id===c.id&&x.driver_id===user?.id);
})}
function driverHQ(){
 const own=joinedRaces(),upcoming=own.filter(r=>['checkin','live'].includes(r.status)||(r.status==='scheduled'&&new Date(r.starts_at)>new Date())),past=own.filter(r=>r.status==='finished'||(!['checkin','live'].includes(r.status)&&new Date(r.starts_at)<=new Date()));
 const next=upcoming[0],standing=standings.find(s=>s.driver_id===user.id),nextChamp=championships.find(c=>c.id===next?.championship_id);
 return `<section class="page"><div class="sectionhead"><div><p class="eyebrow">DRIVER HQ</p><h1>Welcome, ${e(profile.forename)}.</h1><p class="muted">Your championships. Your next challenge.</p></div><a class="button" href="#championships">Join a championship ↗</a></div>${profile.status!=='approved'?`<p class="notice">${profile.status==='pending'?'Your application is awaiting approval. You can join an upcoming championship; race attendance opens once approved.':'Your driver registration is not currently approved. Contact the organiser for help.'}</p>`:''}<div class="stats"><article><small>CHAMPIONSHIP POSITION</small><strong>${standing?'P'+standing.position:'—'}</strong><span>${e(championships.find(c=>c.id===champ)?.name||'Select a championship below')}</span></article><article><small>SEASON POINTS</small><strong>${standing?.points??'—'}</strong><span>Published championship results</span></article><article><small>YOUR CHAMPIONSHIPS</small><strong>${entries.filter(x=>x.driver_id===user.id).length}</strong><span>Manage each race below</span></article></div><article class="next-race"><div><p class="eyebrow">YOUR NEXT RACE</p><h2>${e(next?.title||'Your next grid is waiting.')}</h2><p>${next?e(next.track)+' · '+e(nextChamp?.name):'Join a future championship to build your calendar.'}</p></div>${next?`<div class="race-facts"><div><small>SESSION START · UK</small><strong>${date(next.starts_at)}</strong></div><div><small>FORMAT / DURATION</small><strong>${e(next.format)} · ${next.duration_minutes} minutes</strong></div><div><small>ATTENDANCE DEADLINE</small><strong>${date(new Date(new Date(next.starts_at)-1800000))}</strong></div><div><small>YOUR ATTENDANCE</small><strong>${attendance.some(a=>a.session_id===next.id&&a.driver_id===user.id&&a.attending)?'Confirmed':'Not confirmed'} · ${e(next.status)}</strong></div></div>${next.briefing?`<p class="briefing">${e(next.briefing)}</p>`:''}`:''}</article><section class="calendar-panel"><div class="sectionhead"><div><p class="eyebrow">YOUR SEASON</p><h2>Your calendar</h2></div><div class="buttonrow"><button class="history-button ${showPast?'selected':''}" data-click="past" aria-pressed="${showPast}">Past races (${past.length})</button><a class="button quiet" href="#incident">Report incident ↗</a></div></div><p class="muted">Only championships you have joined appear here. Confirm each race before its attendance deadline.</p>${showPast?(past.length?past.map(r=>`<article class="racecard past-race"><div class="race-detail"><small>${e(championships.find(c=>c.id===r.championship_id)?.name)}</small><h3>${e(r.title)}</h3><p>${e(r.track)} · ${date(r.starts_at)}</p>${badge(r.status)}</div><button data-click="raceresults" data-id="${r.id}">Standings ↗</button></article>`).join(''):empty('No past races in your championships yet.')):raceCards(upcoming,true)}</section><div class="sectionhead"><h2>Championship standings</h2>${championshipPicker()}</div>${standingsTable()}</section>`;
}
function championshipsPage(){return `<section class="page"><div class="sectionhead"><div><p class="eyebrow">THE SEASON SO FAR</p><h1>Championships.</h1></div><button class="primary" data-click="joinchamp">Sign up to a championship ↗</button></div>${entries.filter(x=>x.driver_id===user?.id).length?`<p class="muted">Your entries: ${entries.filter(x=>x.driver_id===user?.id).map(x=>e(championships.find(c=>c.id===x.championship_id)?.name)).join(' · ')}</p>`:''}${championshipPicker()}${standingsTable()}<p class="muted">Entries are available for future championships with open registration. Ongoing championships cannot be joined. Points ties use wins; exact ties share rank.</p></section>`}
function championshipFields(c={}){return input('name','Championship name','text',c.name||'','required maxlength="150"')+input('season','Season','text',c.season||String(new Date().getFullYear()),'required')+input('starts_at','Championship start (device local time)','datetime-local',localInput(c.starts_at),'')+select('published','Visibility',[['false','Draft'],['true','Public']],String(c.published??false))+select('enrollment_open','Championship signups',[['true','Open for future entries'],['false','Closed']],String(c.enrollment_open??true))}
function localInput(value){if(!value)return '';const d=new Date(value);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function raceFields(r={}){return (!r.id?select('championship_id','Championship',championships.map(c=>[c.id,c.name])):'')+input('title','Session title','text',r.title||'','required maxlength="150"')+input('track','Circuit','text',r.track||'','required maxlength="150"')+input('starts_at','Session start (device local time)','datetime-local',localInput(r.starts_at),'required')+input('duration_minutes','Duration (minutes)','number',r.duration_minutes||60,'required min="1" max="1440"')+input('format','Session format','text',r.format||'Race','required maxlength="100"')+textarea('briefing','Driver briefing / next-race information',r.briefing||'','maxlength="5000"')}
function adminPage(page){
 const tabs=`<div class="control-nav"><a class="${page==='admin'?'active':''}" href="#admin">Overview</a><a class="${page==='steward'?'active':''}" href="#steward">Steward</a>${role.role==='admin'?`<a class="${page==='amend'?'active':''}" href="#amend">Amend</a>`:''}</div>`;
 let content='';
 if(page==='admin')content=`<div class="control-overview"><a class="panel overview-card" href="#steward"><span class="eyebrow">01 / RACE DAY</span><h2>Steward</h2><p>Open registration, check drivers in, start racing and manage live decisions.</p><strong>Open race desk ↗</strong></a>${role.role==='admin'?`<a class="panel overview-card" href="#amend"><span class="eyebrow">02 / LEAGUE MANAGEMENT</span><h2>Amend</h2><p>Championships, race details, driver approvals, results and league settings.</p><strong>Manage league ↗</strong></a>`:''}</div><div class="stats"><article><small>UPCOMING RACES</small><strong>${races.filter(r=>r.status==='scheduled').length}</strong><span>Scheduled sessions</span></article><article><small>DRIVER APPLICATIONS</small><strong>${drivers.filter(d=>d.status==='pending').length}</strong><span>Awaiting review</span></article><article><small>OPEN INCIDENTS</small><strong>${reports.filter(r=>r.status!=='resolved').length}</strong><span>Steward review needed</span></article></div>`;
 else if(page==='steward')content=stewardPage();
 else if(role.role!=='admin')content=empty('Amend requires administrator permissions.');
 else content=amendPage();
 return `<section class="page control-page"><p class="eyebrow">Sector Vale Racing / RACE CONTROL</p><h1>${page==='admin'?'Race control.':page==='steward'?'Steward.':'Amend.'}</h1>${tabs}${content}</section>`;
}
function roster(r){return attendance.filter(a=>a.session_id===r.id&&a.attending).map(a=>drivers.find(d=>d.id===a.driver_id)).filter(d=>d?.status==='approved')}
function stewardPage(){
 const r=races.find(r=>r.id===selectedRace);
 if(!r){const list=races.filter(r=>['checkin','live'].includes(r.status)||(r.status==='scheduled'&&new Date(r.starts_at)>new Date())).sort((a,b)=>(a.status==='live'?-1:0)-(b.status==='live'?-1:0)||new Date(a.starts_at)-new Date(b.starts_at));return `<div class="sectionhead"><div><h2>Choose a race</h2><p class="muted">Registration → driver check-in → live penalties</p></div></div>${list.length?list.slice(0,12).map(r=>`<article class="racecard control-race"><div class="race-detail"><small>${e(championships.find(c=>c.id===r.championship_id)?.name)}</small><h3>${e(r.title)}</h3><p>${e(r.track)} · ${date(r.starts_at)} · ${r.duration_minutes} min</p><p>${roster(r).length} registered drivers</p>${badge(r.status)}</div><button class="primary" data-click="${r.status==='scheduled'?'startregistration':'openrace'}" data-id="${r.id}">${r.status==='scheduled'?'Start registration':r.status==='live'?'Live penalties →':'Continue check-in →'}</button></article>`).join(''):empty('No upcoming races. Create sessions in Amend.')}<details class="panel"><summary>Incident review & announcements</summary>${incidentReview()}</details>`}
 const people=roster(r),present=people.filter(d=>checkins.some(k=>k.session_id===r.id&&k.driver_id===d.id&&k.checked_in)),remaining=people.filter(d=>!checkins.some(k=>k.session_id===r.id&&k.driver_id===d.id));
 const steps=`<div class="race-steps"><span class="done">01 Registration</span><span class="${r.status==='checkin'?'current':'done'}">02 Check-in</span><span class="${r.status==='live'?'current':''}">03 Live penalties</span></div>`;
 let list='';
 if(r.status==='checkin')list=`<p class="muted">Select green for present or red for absent beside every driver. ${remaining.length} still to mark.</p><div class="driver-list">${people.map(d=>{const check=checkins.find(k=>k.session_id===r.id&&k.driver_id===d.id);return `<article class="driver-row"><div><h3>${e(d.forename+' '+d.surname)}</h3><small>${check?check.checked_in?'Present':'Absent':'Awaiting decision'}</small></div><div class="checkin-buttons"><button class="absent ${check&&!check.checked_in?'selected':''}" aria-label="Mark ${e(d.forename+' '+d.surname)} absent" aria-pressed="${!!check&&!check.checked_in}" data-click="markdriver" data-id="${d.id}" data-present="false">✕ <span>Absent</span></button><button class="present ${check?.checked_in?'selected':''}" aria-label="Mark ${e(d.forename+' '+d.surname)} present" aria-pressed="${!!check?.checked_in}" data-click="markdriver" data-id="${d.id}" data-present="true">✓ <span>Present</span></button></div></article>`}).join('')||empty('No approved drivers confirmed attendance for this race.')}</div><div class="race-start-bar"><span>${present.length} present · ${people.length-present.length-remaining.length} absent</span><button class="primary large" data-click="startrace" ${remaining.length||!present.length?'disabled':''}>Start →</button></div>`;
 else if(r.status==='live')list=`<div class="sectionhead"><div><h2>Live penalty desk</h2><p class="muted">Only drivers marked present appear here. Select a penalty, choose a reason, then give it.</p></div><button data-click="finishrace">Finish race</button></div><div class="driver-list">${present.map(d=>`<article class="driver-row penalty-driver"><div><h3>${e(d.forename+' '+d.surname)}</h3><div class="penalty-history">${penalties.filter(p=>p.driver_id===d.id&&p.session_id===r.id&&!p.removed_at).map(p=>`<span class="badge" title="${e(p.reason)}">${e(penaltyLabel(p.type,p.seconds))} · ${e(p.reason)}</span>`).join('')||'<small>No decisions</small>'}</div></div><div class="penalty-buttons">${penaltyChoices.map(([type,label,seconds])=>`<button class="penalty-${type}" data-click="givepenalty" data-id="${d.id}" data-type="${type}" data-seconds="${seconds}">${label}</button>`).join('')}</div></article>`).join('')||empty('No drivers checked in.')}</div>`;
 else list=`<p class="notice">This session is ${e(r.status)}. Final classifications and points can be published in Amend.</p><button data-click="raceresults" data-id="${r.id}">View race standings</button>`;
 return `<button class="quiet back-button" data-click="raceslist">← All races</button><div class="sectionhead"><div><h2>${e(r.title)}</h2><p class="muted">${e(r.track)} · ${date(r.starts_at)}</p></div>${badge(r.status)}</div>${steps}${list}<details class="panel support-panel"><summary>Incident review & announcements</summary>${incidentReview()}</details>`;
}
const penaltyChoices=[['disqualification','DQ',0],['drive_through','DT',0],['time','+10',10],['time','+5',5],['warning','Warn',0],['note','Note',0],['investigation','Investigate after race',0]];
const penaltyReasons={warning:['Track limits','Unsafe rejoin','Blocking / weaving','Avoidable contact'],note:['Racing incident noted','Driving standards reminder','Minor contact','Position returned'],time:['Causing a collision','Gaining an advantage','Unsafe pit entry / exit','Repeated track limits'],disqualification:['Dangerous driving','Ignoring steward instructions','Repeated serious offences','Unsporting conduct'],drive_through:['Jump start','Pit-lane speeding','Unsafe rejoin','Repeated avoidable contact'],investigation:['Disputed contact','Evidence review required','Possible rule breach','Driver protest']};
function penaltyLabel(type,seconds){return type==='time'?`+${seconds}s`:({disqualification:'DQ',drive_through:'DT',warning:'Warning',note:'Note',investigation:'Post-race investigation'}[type]||type)}
function incidentReview(){return `<h2>Incident review</h2>${reports.map(r=>`<details><summary>${e(driverName(r.reporter_id))} · ${e(races.find(s=>s.id===r.session_id)?.title)} · ${badge(r.status)}</summary><p>${e(r.details)}</p>${r.evidence_url?`<a href="${e(r.evidence_url)}" target="_blank" rel="noopener">Open evidence ↗</a>`:''}${form('incident_status',`<input type="hidden" name="id" value="${r.id}">`+select('status','Review status',[['submitted','Submitted'],['reviewing','Reviewing'],['resolved','Resolved']],r.status))}</details>`).join('')||empty('No incident reports.')}<h2>League announcement</h2>${form('announcement',textarea('message','Message','','required minlength="3" maxlength="3000"'),'Notify approved drivers')}`}
function amendPage(){
 const sections=[['championships','Championships'],['races','Races & briefings'],['drivers','Driver approvals'],['results','Results & points'],['penalties','Penalty records'],['settings','Settings & signups']];
 let content='';
 if(amendSection==='championships')content=`<h2>Championships</h2><p class="muted">Publish and open future entries. A start date or first scheduled race is required before drivers can join. Ongoing championships are automatically excluded.</p><details class="panel"><summary>Create championship +</summary>${form('championship',championshipFields(),'Create championship')}</details>${championships.map(c=>`<details class="panel"><summary>${e(c.name)} · ${e(c.season)} ${badge(c.published?'Public':'Draft')} ${badge(c.enrollment_open?'Entries open':'Entries closed')}</summary><p class="muted">${entries.filter(x=>x.championship_id===c.id).length} driver entries</p>${form('championship_update',`<input type="hidden" name="id" value="${c.id}">`+championshipFields(c),'Save championship')}<h3>Entered drivers</h3>${entries.filter(x=>x.championship_id===c.id).map(x=>`<p>${e(driverName(x.driver_id))}</p>`).join('')||empty('No entries yet.')}</details>`).join('')}`;
 else if(amendSection==='races')content=`<h2>Races & driver briefings</h2><details class="panel"><summary>Create race +</summary>${championships.length?form('race',raceFields(),'Create race'):empty('Create a championship first.')}</details>${races.map(r=>`<details class="panel"><summary>${e(r.title)} · ${date(r.starts_at)} ${badge(r.status)}</summary>${form('race_update',`<input type="hidden" name="id" value="${r.id}">`+raceFields(r),'Save race details')}<p class="muted">Live/check-in/finished sessions cannot be rescheduled.</p></details>`).join('')}`;
 else if(amendSection==='drivers')content=`<h2>Driver approvals</h2><p class="muted">${drivers.filter(d=>d.status==='pending').length} awaiting review. Approval allows race attendance; championship membership is separate.</p>${[...drivers].sort((a,b)=>(a.status==='pending'?-1:1)-(b.status==='pending'?-1:1)).map(d=>`<details class="panel"><summary>${e(d.forename+' '+d.surname)} · ${badge(d.status)}</summary><p>${e(d.category)} · ${e(levels.find(([v])=>v===d.experience)?.[1]||d.experience)}</p>${form('registration',`<input name="driver_id" type="hidden" value="${d.id}">`+select('status','Registration status',[['pending','Pending'],['approved','Approved'],['rejected','Rejected']],d.status),'Save approval')}</details>`).join('')||empty('No applications.')}`;
 else if(amendSection==='results')content=`<h2>Results & championship points</h2><p class="muted">Finish a race in Steward, then enter the final classification after reviewing time penalties. These results populate the race standings popup and championship table.</p>${form('result',select('session_id','Finished race',races.filter(r=>r.status==='finished').map(r=>[r.id,r.title]))+driverSelect()+input('position','Final position','number','1','required min="1"')+input('points','Championship points','number','0','required min="0" max="1000" step="0.5"'),'Publish result')}<h3>Inspect published race standings</h3><div class="buttonrow">${races.filter(r=>r.status==='finished').map(r=>`<button data-click="raceresults" data-id="${r.id}">${e(r.title)} ↗</button>`).join('')}</div>`;
 else if(amendSection==='penalties')content=`<h2>Penalty records & removals</h2>${penalties.map(p=>`<details class="panel"><summary>${e(driverName(p.driver_id))} · ${e(penaltyLabel(p.type,p.seconds))} ${p.removed_at?'· removed':''}</summary><p>${e(races.find(r=>r.id===p.session_id)?.title)} · ${e(p.reason)}</p>${!p.removed_at?form('remove_penalty',`<input name="id" type="hidden" value="${p.id}">`+input('reason','Reason for removal','text','','required minlength="3"'),'Remove & notify'):`<p>Removal reason: ${e(p.removal_reason)}</p>`}</details>`).join('')||empty('No penalties.')}`;
 else content=`<h2>Settings & public signup</h2><article class="signup-panel"><div><h3>${settings.registration_open?'Signups are open':'Signups are closed'}</h3><p>Existing drivers can sign in in either state.</p></div><button class="primary" data-click="togglesignup" data-enabled="${!settings.registration_open}">${settings.registration_open?'Disable signups':'Enable signups'}</button></article>${form('settings',input('league_name','League name','text',settings.league_name,'required')+input('controller_name','Data controller name','text',settings.controller_name,'required')+input('privacy_email','Contact email','email',settings.privacy_email,'required')+textarea('privacy_text','Privacy notice',settings.privacy_text,'required minlength="50"')+textarea('regulations','Racing regulations',settings.regulations,'required minlength="50"')+`<input type="hidden" name="registration_open" value="${settings.registration_open}">`,'Save league settings')}<p class="muted">Saving policies creates a new policy version.</p>`;
 return `<div class="amend-layout"><aside class="amend-menu" aria-label="Amend sections">${sections.map(([key,label])=>`<button data-click="amendsection" data-id="${key}" class="${amendSection===key?'active':''}" aria-current="${amendSection===key?'page':'false'}">${label}${key==='drivers'?` <span>${drivers.filter(d=>d.status==='pending').length}</span>`:''}</button>`).join('')}</aside><div class="amend-content">${content}</div></div>`;
}
function modalHTML(){
 if(!modalState)return '';
 let title='',body='';
 if(modalState.kind==='join'){
 title='Join a championship';const available=futureChampionships();body=!user?`<p>Sign in or create a driver account to join a championship.</p><a class="button primary" href="#login">Sign in</a>`:available.length?form('join_championship',select('championship_id','Choose a future championship',available.map(c=>[c.id,`${c.name} · ${c.season}`]))+'<p class="muted">Your entry adds this championship to Driver HQ. Confirm attendance separately for each race.</p>','Join championship →'):empty('No future championships are accepting new entries. You may already have joined the available championships.');
 }else if(modalState.kind==='results'){
 title='Race standings';const r=races.find(r=>r.id===modalState.id);body=`<h3>${e(r?.title)}</h3><p class="muted">${e(r?.track)} · ${r?date(r.starts_at):''}</p>${modalState.loading?'<p role="status">Loading standings…</p>':modalState.error?empty(modalState.error):modalState.rows?.length?table(['Pos','Driver','Points'],modalState.rows.map(s=>[s.disqualified?'DQ':s.position,e(s.display_name),s.points])):empty('Final results have not been published for this race yet.')}`;
 }else if(modalState.kind==='penalty'){
 title=`Give ${penaltyLabel(modalState.type,modalState.seconds)}`;body=`<p>${e(driverName(modalState.driverId))} · ${e(races.find(r=>r.id===selectedRace)?.title)}</p>${form('penalty',`<input type="hidden" name="session_id" value="${selectedRace}"><input type="hidden" name="driver_id" value="${modalState.driverId}"><input type="hidden" name="type" value="${modalState.type}"><input type="hidden" name="seconds" value="${modalState.seconds}"><div class="reason-grid">${penaltyReasons[modalState.type].map(reason=>`<button type="button" data-click="penaltyreason" data-reason="${e(reason)}">${e(reason)}</button>`).join('')}</div>`+textarea('reason','Reason (choose above or enter your own)','','required minlength="3" maxlength="2000"'),'Give')}`;
 }
 return `<dialog id="league-modal" aria-labelledby="modal-title"><div class="modal-heading"><h2 id="modal-title">${e(title)}</h2><button class="modal-close quiet" data-click="closemodal" aria-label="Close popup">✕</button></div>${body}</dialog>`;
}
function closeModal(){modalState=null;document.querySelector('#league-modal')?.close();document.querySelector('#league-modal')?.remove()}

root.addEventListener('submit',async event=>{
 const f=event.target;if(!f.dataset.form)return;event.preventDefault();const button=f.querySelector('button[type="submit"]');const originalLabel=button.textContent;button.disabled=true;button.textContent='Please wait…';f.setAttribute('aria-busy','true');
 try{
 const kind=f.dataset.form;const data=Object.fromEntries(new FormData(f));
 if(kind==='register'||kind==='owner_setup'){
 if(kind==='register'){
 const details=validateRegistration({...data,privacy_acknowledged:!!data.privacy_acknowledged,regulations_accepted:!!data.regulations_accepted,marketing_consent:!!data.marketing_consent,policy_version:settings.policy_version});
 const response=await fetch(url+'/functions/v1/register-driver',{method:'POST',headers:{'Content-Type':'application/json',apikey:key,Authorization:'Bearer '+edgeKey},body:JSON.stringify({email:details.email,password:details.password,...details.metadata})});
 const result=await response.json();if(!response.ok)throw new Error(result.error||'Registration is unavailable. Please try again.');
 const login=await db.auth.signInWithPassword({email:details.email,password:details.password});if(login.error){toast('Account created. You can now sign in.');go('login')}else{if(await refresh())go('dashboard');toast('Pre-registration received. Your driver application is awaiting league review; race entry is not confirmed.')}
 return;
 }
 const {email,password,...meta}=data;meta.privacy_acknowledged=kind==='register';meta.regulations_accepted=kind==='register';meta.marketing_consent=!!data.marketing_consent;meta.policy_version=settings.policy_version;
 const result=await db.auth.signUp({email,password,options:{data:meta,emailRedirectTo:location.origin+'/?auth=confirmed'}});if(result.error)throw result.error;
 toast('Check your email to confirm your account, then sign in.');go('login');
 }else if(kind==='login'){
 const result=await db.auth.signInWithPassword(data);if(result.error)throw result.error;if(await refresh())go('dashboard');
 }else if(kind==='reset'){
 const result=await db.auth.resetPasswordForEmail(data.email,{redirectTo:location.origin+'/?auth=recovery'});if(result.error)throw result.error;toast('If the account exists, a reset email has been requested.');
 }else if(kind==='password'){
 const result=await db.auth.updateUser({password:data.password});if(result.error)throw result.error;toast('Password updated.');go('dashboard');await refresh();
 }else if(kind==='verify'){
 const result=await db.auth.mfa.challengeAndVerify({factorId:factor,code:data.code});if(result.error)throw result.error;factor=null;qr='';setupKey='';toast('Authenticator verified.');go(role.role==='driver'?'profile':'admin');await refresh();
 }else{
 if(kind==='profile')data.marketing_consent=!!data.marketing_consent;
 if(['race','race_update','championship','championship_update'].includes(kind)&&data.starts_at)data.starts_at=new Date(data.starts_at).toISOString();
 if(kind==='penalty'&&data.type!=='time')data.seconds=0;
 if(['checked_in','published','registration_open','enrollment_open'].some(k=>k in data))for(const k of ['checked_in','published','registration_open','enrollment_open'])if(k in data)data[k]=data[k]==='true';
 await action(kind,data);if(['penalty','join_championship'].includes(kind))closeModal();toast(kind==='penalty'?'Penalty given. Driver notified.':kind==='join_championship'?'Championship joined. Your HQ calendar is updated.':'Saved successfully.');await refresh();
 }
 }catch(err){toast(err.message)}finally{button.disabled=false;button.textContent=originalLabel;f.removeAttribute('aria-busy')}
});
root.addEventListener('change',async event=>{
 const target=event.target;
 try{
 if(target.name==='championship'){champ=target.value;standings=await query(db.rpc('championship_standings',{championship:champ}));render()}
 if(target.dataset.attend){target.disabled=true;await action('attend',{session_id:target.dataset.attend,attending:target.checked});await refresh();toast('Attendance updated.')}
 if(target.id==='reason-preset')target.closest('form').elements.reason.value=target.value;
 }catch(err){toast(err.message);await refresh()}
});
root.addEventListener('click',async event=>{
 const target=event.target.closest('[data-click],[data-read]');if(!target)return;
 try{
 if(target.dataset.read){await action('read',{id:target.dataset.read});await refresh()}
 if(target.dataset.click==='closemodal'){closeModal();return}
 if(target.dataset.click==='joinchamp'){modalState={kind:'join'};render();return}
 if(target.dataset.click==='raceresults'){modalState={kind:'results',id:target.dataset.id,loading:true};render();try{const rows=await query(db.rpc('race_standings',{session:target.dataset.id}));if(modalState?.kind==='results'&&modalState.id===target.dataset.id){modalState={...modalState,rows,loading:false};render()}}catch(err){if(modalState?.kind==='results'){modalState={...modalState,error:err.message,loading:false};render()}}return}
 if(target.dataset.click==='past'){showPast=!showPast;render();return}
 if(target.dataset.click==='amendsection'){amendSection=target.dataset.id;render();return}
 if(target.dataset.click==='raceslist'){selectedRace='';render();return}
 if(target.dataset.click==='openrace'){selectedRace=target.dataset.id;render();return}
 if(target.dataset.click==='startregistration'){target.disabled=true;await action('start_registration',{session_id:target.dataset.id});selectedRace=target.dataset.id;await refresh();toast('Registration opened. Registered drivers notified.');return}
 if(target.dataset.click==='markdriver'){target.disabled=true;await action('checkin',{session_id:selectedRace,driver_id:target.dataset.id,checked_in:target.dataset.present==='true'});await refresh();return}
 if(target.dataset.click==='startrace'){target.disabled=true;await action('session_state',{session_id:selectedRace,status:'live'});await refresh();toast('Race started. Live penalties are ready.');return}
 if(target.dataset.click==='finishrace'){target.disabled=true;await action('session_state',{session_id:selectedRace,status:'finished'});await refresh();toast('Race finished. Publish results in Amend.');return}
 if(target.dataset.click==='givepenalty'){modalState={kind:'penalty',driverId:target.dataset.id,type:target.dataset.type,seconds:Number(target.dataset.seconds)};render();return}
 if(target.dataset.click==='penaltyreason'){const f=target.closest('form');f.elements.reason.value=target.dataset.reason;f.querySelectorAll('[data-click="penaltyreason"]').forEach(b=>b.classList.toggle('selected',b===target));return}
 if(target.dataset.click==='retry')await refresh();
 if(target.dataset.click==='togglesignup'){target.disabled=true;const enabled=target.dataset.enabled==='true';await action('signup_toggle',{enabled});await refresh();toast(enabled?'Signups enabled. New drivers can register.':'Signups disabled. Existing accounts can still sign in.')}
 
 if(target.dataset.click==='logout'){const {error}=await db.auth.signOut();if(error)throw error;factor=null;qr='';setupKey='';go('home');await refresh()}
 if(target.dataset.click==='prevslide'||target.dataset.click==='nextslide'){slide=(slide+(target.dataset.click==='nextslide'?1:2))%3;paintSlides()}
 if(target.dataset.click==='copysetupkey'){if(!setupKey)throw new Error('Start authenticator setup first.');await navigator.clipboard.writeText(setupKey);toast('Setup key copied. Paste it into your authenticator app.')}
 if(target.dataset.click==='setupmfa'){
 target.disabled=true;const factors=await query(db.auth.mfa.listFactors());const verified=factors.totp.find(f=>f.status==='verified');
 if(verified){factor=verified.id;qr='';setupKey=''}else{for(const pending of factors.all.filter(f=>f.status==='unverified'&&f.factor_type==='totp')){const {error}=await db.auth.mfa.unenroll({factorId:pending.id});if(error)throw error}const enrolled=await query(db.auth.mfa.enroll({factorType:'totp',friendlyName:'Sector Vale Racing authenticator'}));factor=enrolled.id;setupKey=enrolled.totp.secret;qr=enrolled.totp.qr_code.startsWith('data:')?enrolled.totp.qr_code:'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(enrolled.totp.qr_code)}render();
 }
 }catch(err){toast(err.message);target.disabled=false}
});
root.addEventListener('cancel',event=>{if(event.target.id==='league-modal'){event.preventDefault();closeModal()}},true);
window.addEventListener('hashchange',()=>{closeModal();render();if(route()!=='series')window.scrollTo(0,0)});
if(db)db.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT'){factor=null;qr='';setupKey=''}if(event==='PASSWORD_RECOVERY')go('password');if(['SIGNED_OUT','TOKEN_REFRESHED','MFA_CHALLENGE_VERIFIED'].includes(event))setTimeout(refresh,0)});
setInterval(()=>{if(document.visibilityState==='visible'&&user&&!root.querySelector('form'))refresh()},30000);
function paintSlides(){root.querySelectorAll('.slide').forEach((el,index)=>el.classList.toggle('active',index===slide))}
setInterval(()=>{if(route()==='home'&&!slideshowPaused&&document.visibilityState==='visible'){slide=(slide+1)%3;paintSlides()}},7000);
setInterval(()=>{document.querySelectorAll('[data-attend]').forEach(el=>{const r=races.find(r=>r.id===el.dataset.attend);if(r&&(!canAttend(r.starts_at,Date.now(),r.status)||r.status!=='scheduled'))el.disabled=true})},1000);
shell(`<section class="page narrow loading-screen" aria-busy="true"><div class="loading-spinner" aria-hidden="true"></div><h1>Getting the grid ready.</h1><p>Loading your league…</p></section>`);
await refresh();
